// initialization of jquery and datatables.net for standalone version

const $ = require('jquery');

// console.log(`[LOADED] jquery@${$().jquery}`);

if (typeof window !== 'undefined') {
  window.jQuery = $;
  window.$ = $;
}

// Disable AMD while loading datatables.net so it registers on the global jQuery object.
const originalDefine = typeof window !== 'undefined' ? window.define : undefined;
if (typeof window !== 'undefined') {
  window.define = undefined;
}

const datatables = require('datatables.net');

if (typeof window !== 'undefined') {
  window.define = originalDefine;
}

// https://github.com/aurelia/skeleton-navigation/issues/473
datatables(window, $);
// console.log(`[LOADED] datatables.net@${$().DataTable.version}`);
